def _make_sandbox_json(sandboxes):
    """Build JSON output matching openshell sandbox list --output json."""
    return json.dumps(
        [
            {
                "name": sb["name"],
                "phase": sb.get("phase", "Ready"),
                "created_at": sb.get("created_at", "2026-06-02 12:00:00"),
                "id": sb.get("id", "fake-uuid"),
            }
            for sb in sandboxes
        ]
    )


class TestDiscoverSandboxSessions:
    def test_discovers_ready_sandbox(self, tmp_path):
        sandbox_dir = tmp_path / "my-sandbox"
        sandbox_dir.mkdir()
        json_out = _make_sandbox_json([{"name": "my-sandbox"}])
        mock_result = MagicMock(returncode=0, stdout=json_out)

        with (
            patch("claude_dashboard.session.SANDBOXES_DIR", tmp_path),
            patch("subprocess.run", return_value=mock_result),
        ):
            sessions = discover_sandbox_sessions()

        assert len(sessions) == 1
        assert sessions[0].session_id == "sandbox-my-sandbox"
        assert sessions[0].cwd == str(sandbox_dir)
        assert sessions[0].entrypoint == "sandbox"
        assert sessions[0].pid == 0

