class TestSandboxForeground:
    def test_sandbox_uses_code_cli(self):
        from claude_dashboard.platform.linux import foreground_window_linux

        container = ContainerInfo(container_type=ContainerType.SANDBOX)
        mock_result = MagicMock(returncode=0)

        with patch("subprocess.run", return_value=mock_result) as mock_run:
            result = foreground_window_linux(container, cwd="/tmp/sandbox/project")

        assert result is True
        mock_run.assert_called_once()
        args = mock_run.call_args[0][0]
        assert args == ["code", "/tmp/sandbox/project"]

    def test_sandbox_no_cwd_falls_through(self):
        from claude_dashboard.platform.linux import foreground_window_linux

        container = ContainerInfo(container_type=ContainerType.SANDBOX)

        with patch("claude_dashboard.platform.linux._find_window_id_for_session", return_value=0):
            result = foreground_window_linux(container, cwd="")

        assert result is False
